The issue is regarding the export format resetting every time a user opens a report, rather than remembering the previously selected format. The relevant code for handling the export format is in the `src/components/ExportButton.tsx` file. The `ExportButton` component initializes the format using a `defaultFormat` prop, which defaults to "csv". There is currently no mechanism to remember or persist the format between sessions.

To address this issue, a feature needs to be implemented to remember the export format across sessions, potentially using `localStorage` or a similar client-side solution for persistence. This would ensure that the user's last selected format is remembered and used as the default when they open a report next time.

```tsx
interface ExportButtonProps {
  reportId: string;
  defaultFormat?: ExportFormat;
}

export function ExportButton({ reportId, defaultFormat = "csv" }: ExportButtonProps) {
  const [busy, setBusy] = useState(false);
  const [format, setFormat] = useState<ExportFormat>(defaultFormat);
  const toast = useToast();

  const handleClick = () => {
    setBusy(true);
    exportReport(reportId, format).then(() => {
      setBusy(false);
      toast.show(t("ui.export.done"), "success");
    });
  };

  return (
    <div className="export-button">
      <select
        aria-label={t("ui.export.format")}
        value={format}
        disabled={busy}
        onChange={(e) => setFormat(e.target.value as ExportFormat)}
      >
        {SUPPORTED_FORMATS.map((f) => (
          <option key={f} value={f}>
            {f.toUpperCase()}
          </option>
        ))}
      </select>
      <button type="button" onClick={handleClick} disabled={busy}>
        {busy ? t("ui.export.busy") : t("ui.export.button")}
      </button>
    </div>
  );
}
